import{_ as s,o as a,c as n,ag as l}from"./chunks/framework.DKalukzk.js";const g=JSON.parse('{"title":"Tableaux croisés dynamiques","description":"","frontmatter":{"title":"Tableaux croisés dynamiques"},"headers":[],"relativePath":"modules/02-excel/11-tableaux-croises.md","filePath":"modules/02-excel/11-tableaux-croises.md"}'),i={name:"modules/02-excel/11-tableaux-croises.md"};function r(o,e,t,u,c,d){return a(),n("div",null,[...e[0]||(e[0]=[l(`<h1 id="tableaux-croises-dynamiques" tabindex="-1">Tableaux croisés dynamiques <a class="header-anchor" href="#tableaux-croises-dynamiques" aria-label="Permalink to &quot;Tableaux croisés dynamiques&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p><a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQDn0qZv6FmVSp3woKi1POtxAWXEnHhU7xkTgiR1J-hHdkU?e=ZKaWnL" target="_blank" rel="noreferrer">11 – Tableaux croisés dynamiques</a></p><p>⚠️ Ne travaillez pas dans la version Excel du navigateur Web.</p><p><strong>Veuillez télécharger une copie de chaque exercice.</strong></p><ul><li>Fichier --&gt; Créer une copie --&gt; Télécharger une copie</li></ul><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><ul><li>Créer un tableau croisé dynamique pour synthétiser rapidement de grandes quantités de données</li><li>Restructurer les données selon différentes dimensions (lignes, colonnes, filtres)</li><li>Calculer des totaux, moyennes et comptes sans écrire de formules</li><li>Analyser les données selon plusieurs critères simultanément</li></ul><h2 id="concepts-cles" tabindex="-1">Concepts clés <a class="header-anchor" href="#concepts-cles" aria-label="Permalink to &quot;Concepts clés&quot;">​</a></h2><h3 id="qu-est-ce-qu-un-tableau-croise-dynamique" tabindex="-1">Qu&#39;est-ce qu&#39;un tableau croisé dynamique ? <a class="header-anchor" href="#qu-est-ce-qu-un-tableau-croise-dynamique" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un tableau croisé dynamique ?&quot;">​</a></h3><p>Un tableau croisé dynamique est un outil qui <strong>résume et réorganise</strong> les données d&#39;une liste pour en faciliter l&#39;analyse.</p><p><strong>Avantages :</strong></p><ul><li>Synthèse immédiate de gros volumes de données</li><li>Permet de croiser plusieurs dimensions (ex. : Produits × Mois × Régions)</li><li>Mise à jour automatique si les données changent</li><li>Pas besoin de formules complexes</li></ul><h3 id="regle-d-or" tabindex="-1">Règle d&#39;or <a class="header-anchor" href="#regle-d-or" aria-label="Permalink to &quot;Règle d&#39;or&quot;">​</a></h3><p>⚠️ <strong>Les données doivent être propres et bien structurées</strong> :</p><ul><li>Pas de cellules fusionnées</li><li>Pas de lignes/colonnes vides au milieu</li><li>En-têtes dans la première ligne</li><li>Pas de totaux préexistants</li></ul><h2 id="creer-un-tableau-croise-dynamique" tabindex="-1">Créer un tableau croisé dynamique <a class="header-anchor" href="#creer-un-tableau-croise-dynamique" aria-label="Permalink to &quot;Créer un tableau croisé dynamique&quot;">​</a></h2><h3 id="ou-est-le-bouton" tabindex="-1">Où est le bouton ? <a class="header-anchor" href="#ou-est-le-bouton" aria-label="Permalink to &quot;Où est le bouton ?&quot;">​</a></h3><ul><li>Onglet <strong>Insertion</strong> du ruban</li><li>Groupe <strong>Tableaux</strong></li><li>Bouton <strong>Tableau croisé dynamique</strong> (ou <strong>Pivot Table</strong>)</li></ul><h3 id="procedure" tabindex="-1">Procédure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procédure&quot;">​</a></h3><ol><li>Sélectionner <strong>toute la plage de données</strong> (y compris les en-têtes)</li><li>Aller dans <strong>Insertion</strong> &gt; <strong>Tableau croisé dynamique</strong></li><li>Vérifier que la plage est correcte</li><li>Choisir où placer le tableau croisé : <ul><li><strong>Nouvelle feuille</strong> (recommandé) ou</li><li><strong>Feuille existante</strong> (indiquer une cellule)</li></ul></li><li>Cliquer sur <strong>Créer</strong></li><li>Une nouvelle interface apparaît avec des <strong>champs</strong> à glisser</li></ol><h3 id="configuration-des-zones" tabindex="-1">Configuration des zones <a class="header-anchor" href="#configuration-des-zones" aria-label="Permalink to &quot;Configuration des zones&quot;">​</a></h3><p>Un tableau croisé dynamique a 4 zones principales :</p><ul><li><strong>Filtres</strong> : filtrer les données selon un critère (ex. : par région)</li><li><strong>Colonnes</strong> : les champs qui seront en en-têtes de colonnes (ex. : les mois)</li><li><strong>Lignes</strong> : les champs qui seront en en-têtes de lignes (ex. : les produits)</li><li><strong>Valeurs</strong> : ce qu&#39;on veut calculer (totaux, moyennes, comptes, etc.)</li></ul><h3 id="exemple-analyser-les-ventes-par-produit-et-mois" tabindex="-1">Exemple : analyser les ventes par produit et mois <a class="header-anchor" href="#exemple-analyser-les-ventes-par-produit-et-mois" aria-label="Permalink to &quot;Exemple : analyser les ventes par produit et mois&quot;">​</a></h3><p><strong>Données source :</strong></p><ul><li>Colonnes : Produit, Mois, Région, Quantité vendue</li></ul><p><strong>Configuration du tableau croisé :</strong></p><ul><li><strong>Lignes</strong> : Produit</li><li><strong>Colonnes</strong> : Mois</li><li><strong>Valeurs</strong> : Somme de Quantité vendue</li><li><strong>Filtres</strong> : Région (optionnel, pour filtrer par région)</li></ul><p><strong>Résultat :</strong> un tableau qui montre les ventes de chaque produit par mois, avec les totaux.</p><h2 id="modifier-le-tableau-croise-dynamique" tabindex="-1">Modifier le tableau croisé dynamique <a class="header-anchor" href="#modifier-le-tableau-croise-dynamique" aria-label="Permalink to &quot;Modifier le tableau croisé dynamique&quot;">​</a></h2><h3 id="changer-l-ordre-des-champs" tabindex="-1">Changer l&#39;ordre des champs <a class="header-anchor" href="#changer-l-ordre-des-champs" aria-label="Permalink to &quot;Changer l&#39;ordre des champs&quot;">​</a></h3><ul><li>Glisser-déposer un champ d&#39;une zone à l&#39;autre dans le volet <strong>Champs du tableau croisé</strong></li></ul><h3 id="ajouter-un-filtre" tabindex="-1">Ajouter un filtre <a class="header-anchor" href="#ajouter-un-filtre" aria-label="Permalink to &quot;Ajouter un filtre&quot;">​</a></h3><ul><li>Glisser un champ vers la zone <strong>Filtres</strong></li><li>Utiliser la liste déroulante qui apparaît en haut du tableau croisé</li></ul><h3 id="modifier-le-calcul" tabindex="-1">Modifier le calcul <a class="header-anchor" href="#modifier-le-calcul" aria-label="Permalink to &quot;Modifier le calcul&quot;">​</a></h3><ol><li>Double-cliquer sur un champ dans la zone <strong>Valeurs</strong></li><li>Choisir l&#39;agrégation : <ul><li><strong>Somme</strong> : addition</li><li><strong>Moyenne</strong> : moyenne</li><li><strong>Compte</strong> : nombre de cellules</li><li><strong>Min/Max</strong> : valeur minimale/maximale</li><li>Etc.</li></ul></li></ol><h3 id="rafraichir-les-donnees" tabindex="-1">Rafraîchir les données <a class="header-anchor" href="#rafraichir-les-donnees" aria-label="Permalink to &quot;Rafraîchir les données&quot;">​</a></h3><ul><li>Cliquer sur le tableau croisé</li><li><strong>Données</strong> &gt; <strong>Actualiser</strong></li><li>Les modifications apportées aux données sources seront reflétées</li></ul><h2 id="exercice-analyser-les-ventes-d-une-boutique" tabindex="-1">Exercice : Analyser les ventes d&#39;une boutique <a class="header-anchor" href="#exercice-analyser-les-ventes-d-une-boutique" aria-label="Permalink to &quot;Exercice : Analyser les ventes d&#39;une boutique&quot;">​</a></h2><h3 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h3><p>Vous disposez d&#39;une liste de ventes avec les colonnes suivantes :</p><ul><li><strong>Date</strong> : date de la vente</li><li><strong>Produit</strong> : nom du produit vendu</li><li><strong>Catégorie</strong> : type de produit (Électronique, Vêtements, Accessoires)</li><li><strong>Quantité</strong> : nombre d&#39;articles vendus</li><li><strong>Prix_unitaire</strong> : prix par article</li><li><strong>Montant</strong> : montant total de la vente (Quantité × Prix_unitaire)</li><li><strong>Vendeur</strong> : nom du vendeur</li></ul><h3 id="instructions-pour-excel" tabindex="-1">Instructions pour Excel <a class="header-anchor" href="#instructions-pour-excel" aria-label="Permalink to &quot;Instructions pour Excel&quot;">​</a></h3><p><strong>À coller dans une cellule de votre classeur :</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXERCICE - TABLEAUX CROISÉS DYNAMIQUES</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Créez 4 tableaux croisés dynamiques pour répondre aux questions :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1️) Montant TOTAL par CATÉGORIE</span></span>
<span class="line"><span>   Lignes: Catégorie | Valeurs: Somme de Montant</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2) Montant par PRODUIT et PAR MOIS</span></span>
<span class="line"><span>   Lignes: Produit | Colonnes: Mois (de Date) | Valeurs: Somme de Montant</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3️) QUANTITÉ vendue par VENDEUR</span></span>
<span class="line"><span>   Lignes: Vendeur | Valeurs: Somme de Quantité</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4) Montant par CATÉGORIE ET VENDEUR</span></span>
<span class="line"><span>   Lignes: Catégorie | Colonnes: Vendeur | Valeurs: Somme de Montant</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ÉTAPES:</span></span>
<span class="line"><span>• Sélectionner toutes les données (en-têtes inclus)</span></span>
<span class="line"><span>• Insertion &gt; Tableau croisé dynamique &gt; Créer</span></span>
<span class="line"><span>• Glisser les champs dans les zones appropriées</span></span>
<span class="line"><span>• Chaque tableau croisé = nouvelle feuille</span></span>
<span class="line"><span></span></span>
<span class="line"><span>⚠️ Les données doivent être propres (pas d&#39;espaces vides, pas de fusion)</span></span></code></pre></div><h3 id="points-cles" tabindex="-1">Points clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points clés&quot;">​</a></h3><ul><li>Commencez par le tableau croisé le plus simple (question 1)</li><li>Testez différentes configurations pour explorer les données</li><li>Créez chaque tableau croisé dans une feuille séparée</li><li>Les données sources restent inchangées</li></ul>`,48)])])}const h=s(i,[["render",r]]);export{g as __pageData,h as default};
